INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Meilensteine in IT-Projekten immer am Projektende liegen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Verteilt über Projektlaufzeit"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Meilensteine für ein IT-Projekt definiere?', 3, '[{"text": "Klar definierte Ziele", "correct": true, "because": "Sichern Fortschritt"}, {"text": "Schnellste Festlegung", "correct": false, "because": "Planung zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Meilensteine in IT-Projekten?', 5, '[{"text": "Klar definiert", "correct": true, "because": "Markieren Etappen"}, {"text": "Messbar", "correct": true, "because": "Überprüfen Fortschritt"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Meilensteine dienen der Projektkontrolle. b) Sie sind immer unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wichtig für Kontrolle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Meilensteine für ein IT-Projekt festlege?', 4, '[{"text": "Projektziele", "correct": false, "because": "Bestimmen Meilensteine"}, {"text": "Zeitplan", "correct": false, "because": "Koordiniert Etappen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Projektfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Meilensteine in IT-Projekten immer zeitlich fixiert sind?', 2, '[{"text": "Ja", "correct": true, "because": "Markieren Deadlines"}, {"text": "Nein", "correct": false, "because": "Grundprinzip"}]'),
